-- MySQL production configuration; execute without --force.
CREATE TEMPORARY TABLE rollout_assert (ok INT NOT NULL CHECK(ok=1));
START TRANSACTION;
SELECT id FROM channels WHERE id IN (2,3) FOR UPDATE;
SELECT `key` FROM options WHERE `key` IN ('ModelRatio','CompletionRatio','CacheRatio','CreateCacheRatio','GroupModelRatio','billing_setting.billing_expr','billing_setting.billing_mode') FOR UPDATE;
